# -*- coding: utf-8 -*-
from common import *
NEW=[]
def q4(ch,p,quote,disp=None):
    if not chk(ch,p,quote): raise SystemExit(f'BAD NEW QUOTE ch{ch} p{p}: {quote}')
    return ['T4',f'2026 교안 Ch.{ch}',f'p.{p}',disp or quote]
def nq(ch,k,q,o,a,exp,ev,conf='상',fig=None):
    NEW.append(dict(id=f'N-{ch}-{sum(1 for x in NEW if x["ch"]==ch)+1:02d}',ch=ch,k=k,q=q,o=o,a=a,exp=exp,ev=ev,conf=conf,fig=fig))
# ---- Ch1
nq(1,'1.Sertürner','1805년 Friedrich Sertürner가 opium에서 morphine을 정제한 이후 약리학에서 확고해진 설명으로 가장 적절한 것은?',['약리작용은 구조가 밝혀지지 않으면 설명할 수 없다.','구조가 밝혀지지 않아도 약리작용은 식물에 함유된 chemical에 의한다는 설명이 확고해졌다.','약물은 수용체와 무관하게 전신에 균등 분포하여 작용한다.','약리작용은 미생물에 의해서만 나타난다.','합성화학은 약리학과 무관함이 입증되었다.'],[2],'교안 p.6은 morphine 정제 이후 “구조가 밝혀지지 않아도 약리작용을 나타내는 데는 plant에 함유되는 chemical에 의한다는 설명이 확고해짐”이라고 서술한다.',[q4(1,6,'1805년, Friedrich Sertürner : opium에서 morphine 정제'),q4(1,6,'plant에 함유되는 chemical에 의한다는 설명이 확고해짐')])
